const fig=(title,o)=>({t:'figure',title,dots:'',...o,hide:Object.keys(o.pts||{}).join('')});
const board=(title,lines)=>({t:'board',title,lines,box:true});
const tab=(title,rows,cols)=>({t:'setups',title,head:'',rows,cols});
const bars=(title,labels,values)=>({t:'chart',kind:'bars',title,bars:labels.map((label,i)=>({label,value:values[i]}))});
const choose=(right,wrong,k)=>{const o=[...wrong];o.splice(k%3,0,right);return {text:o.map((x,i)=>`${'ABC'[i]}: ${x}`).join(', '),letter:'ABC'[o.indexOf(right)]};};
const scenario=(title,p)=>{const lines=[];let line='';for(const word of p.split(' ')){if((line+' '+word).length>49){lines.push(line);line=word;}else line+=(line?' ':'')+word;}if(line)lines.push(line);return {t:'board',title,lines};};
const flow=(title,labels,foot)=>{const pts={},polys=[],segs=[],notes=[];labels.forEach((text,i)=>{const x=i*9;Object.assign(pts,{['A'+i]:[x,0],['B'+i]:[x+7,0],['C'+i]:[x+7,3],['D'+i]:[x,3]});polys.push({v:`A${i}B${i}C${i}D${i}`,col:i%4});notes.push({at:[x+3.5,1.5],text});if(i){pts['E'+i]=[x-2,1.5];pts['F'+i]=[x,1.5];segs.push({v:`E${i}F${i}`,arrows:1,col:1});}});notes.push({at:[(labels.length*9-2)/2,-2],text:foot});return fig(title,{pts,polys,segs,notes,view:[-1,labels.length*9-1,-4,6]});};
const PAIR=fig('DNA: paired strands run in opposite directions',{pts:{A:[2,3],B:[26,3],C:[2,-1],D:[26,-1]},segs:[{v:'AB',col:0},{v:'CD',col:1}],notes:[{at:[0,3],text:'5′'},{at:[28,3],text:'3′'},{at:[0,-1],text:'3′'},{at:[28,-1],text:'5′'},...[['A','T'],['G','C'],['T','A'],['C','G']].flatMap(([a,b],i)=>[{at:[5+6*i,2.3],text:a},{at:[5+6*i,-.3],text:b},{at:[5+6*i,1],text:'⋮'}]),{at:[14,5.2],text:'covalent sugar–phosphate backbones'},{at:[14,-3.2],text:'hydrogen bonds between complementary bases'}],view:[-1,29,-4.5,6]});
const CONSERVE=(()=>{const pts={},segs=[],notes=[];[[2,3,0,0],[12,3,0,1],[22,3,1,0]].forEach(([x,y,c1,c2],i)=>{for(let j=0;j<2;j++){pts['A'+(2*i+j)]=[x,y-j];pts['B'+(2*i+j)]=[x+6,y-j];segs.push({v:`A${2*i+j}B${2*i+j}`,col:j?c2:c1,w:5});}notes.push({at:[x+3,5],text:i?'daughter '+i:'parent'});});notes.push({at:[15,0],text:'blue: parental strand     orange: new strand'},{at:[15,-2],text:'each daughter duplex keeps ONE parental strand'});return fig('Semiconservative copying (schematic)',{pts,segs,notes,view:[0,30,-4,7]});})();
const FORK=fig('One replication fork moving right (schematic)',{pts:{A:[1,4],B:[19,0],C:[29,0],D:[1,-4],E:[29,-.7],F:[19,-.7],G:[3,2.5],H:[16,.1],I:[7,-2],J:[3,-3],K:[13,-.7],L:[9,-1.7]},segs:[{v:'AB',col:0},{v:'BC',col:0},{v:'DF',col:0},{v:'FE',col:0},{v:'GH',col:1,arrows:1},{v:'IJ',col:2,arrows:1},{v:'KL',col:2,arrows:1}],notes:[{at:[1,5.2],text:'3′ template'},{at:[1,-5.3],text:'5′ template'},{at:[27,1.5],text:'5′'},{at:[27,-2],text:'3′'},{at:[10,4.4],text:'leading: 5′ → 3′'},{at:[13,-4.5],text:'lagging: 3′ ← 5′'},{at:[22,3.4],text:'helicase →'},{at:[18,-6.5],text:'ligase seals nicks after primer replacement'}],view:[-1,31,-8,7]});
const SPLICE=(()=>{const pts={},polys=[],notes=[];const blocks=(y,parts)=>{let x=1;parts.forEach(([label,n,col],i)=>{const k=Object.keys(pts).length;Object.assign(pts,{['A'+k]:[x,y],['B'+k]:[x+n,y],['C'+k]:[x+n,y+2],['D'+k]:[x,y+2]});polys.push({v:`A${k}B${k}C${k}D${k}`,col});notes.push({at:[x+n/2,y+1],text:label});x+=n;});};blocks(3,[['E1',6,0],['intron',4,1],['E2',8,2],['intron',4,1],['E3',6,3]]);blocks(-1,[['E1',6,0],['E2',8,2],['E3',6,3]]);notes.push({at:[15,6.4],text:'fictional pre-mRNA: segment widths follow lengths'},{at:[14,-3],text:'retain 60 + 80 + 60 = 200 nt (before cap/tail)'},{at:[14,-4.7],text:'alternative splicing can retain E1 + E3 instead'});return fig('Remove introns; join selected exons',{pts,polys,notes,view:[0,30,-6,8]});})();
const OPERON=fig('Inducible operon (schematic; other inputs fixed)',{pts:{A:[1,2],B:[29,2],C:[3,1],D:[8,1],E:[8,3],F:[3,3],G:[10,1],H:[14,1],I:[14,3],J:[10,3],K:[16,1],L:[28,1],M:[28,3],N:[16,3],O:[12,4.5],P:[12,3.8],Q:[12,3]},segs:[{v:'AB',col:0},{v:'PQ',col:3,arrows:1}],polys:[{v:'CDEF',col:0},{v:'GHIJ',col:1},{v:'KLMN',col:2}],circles:[{c:'O',r:.7,col:3}],notes:[{at:[5.5,2],text:'promoter'},{at:[12,2],text:'operator'},{at:[22,2],text:'enzyme genes'},{at:[21,4.5],text:'repressor binds operator'},{at:[15,-.3],text:'no inducer: repressor blocks transcription'},{at:[15,-2],text:'inducer inactivates repressor: transcription rises'}],view:[0,30,-4,7]});
const CHROMATIN=fig('Access and recruitment regulate transcription',{pts:{A:[2,0],B:[28,0],C:[3,-.6],D:[8,-.6],E:[8,.6],F:[3,.6],G:[20,-.6],H:[26,-.6],I:[26,.6],J:[20,.6],K:[8,0],L:[20,0],M:[10,3],N:[14,4],O:[18,3]},segs:[{v:'AK',col:0},{v:'KM',col:0},{v:'MN',col:0},{v:'NO',col:0},{v:'OL',col:0},{v:'LB',col:0},{v:'KL',col:3,dash:true,arrows:1}],polys:[{v:'CDEF',col:3},{v:'GHIJ',col:1}],notes:[{at:[5.5,-1.7],text:'enhancer + activator'},{at:[23,-1.7],text:'promoter + machinery'},{at:[14,5],text:'looped intervening DNA'},{at:[15,-3.5],text:'dashed link: regulatory protein interaction'},{at:[15,-5],text:'open chromatin generally makes DNA more accessible'}],view:[0,30,-6,6]});
const CELLS=(()=>{const pts={O:[5,.5],N:[5,.5],A:[17,2.6],B:[30,2.6],C:[30,-1.6],D:[17,-1.6],N1:[18,-1.2],N2:[24,2.2],N3:[29,-1.2]},segs=[],circles=[{c:'O',r:1.3,col:0},{c:'N',r:.45,col:3},...['N1','N2','N3'].map(c=>({c,r:.22,col:3}))];let k=0;const line=(a,b,col=0,w=2)=>{const i=k++;pts['P'+i]=a;pts['Q'+i]=b;segs.push({v:`P${i}Q${i}`,col,w});};for(const [a,b] of [[[4,1.3],[2,2.5]],[[2,2.5],[1,2.1]],[[2,2.5],[2,3.3]],[[4,-.3],[2,-1.3]],[[2,-1.3],[1,-.8]],[[2,-1.3],[2,-2.3]],[[5,1.8],[5,3]],[[5,3],[4,3.5]],[[5,3],[6,3.5]],[[6.3,.5],[12,.5]],[[12,.5],[13,1.4]],[[12,.5],[13,-.4]]])line(a,b);for(const y of [-.5,.5,1.5])line([17,y],[30,y],1,1);for(let x=19;x<30;x+=2)line([x,-.8],[x,1.8],1,2);return fig('Cell specialization (schematics, not to scale)',{pts,segs,circles,polys:[{v:'ABCD',col:1,fill:false}],notes:[{at:[6,4.5],text:'neuron portion'},{at:[23.5,4.5],text:'skeletal muscle fiber segment'},{at:[7,-3.4],text:'ion channels: signaling'},{at:[24,-3.4],text:'contractile proteins: force'},{at:[15.5,-5.2],text:'different expression programs; many genes expressed in both'}],view:[0,31,-6,6]});})();
const GEL=fig('Fictional gel: equal-length bands align (schematic)',{pts:{A:[4,4],B:[26,4],C:[26,-4],D:[4,-4],E:[7,3],F:[10,3],G:[14,3],H:[17,3],I:[21,3],J:[24,3],K:[7,0],L:[10,0],M:[7,-2.5],N:[10,-2.5],O:[14,0],P:[17,0],Q:[14,-2.5],R:[17,-2.5],S:[21,1],T:[24,1],U:[21,-2.5],V:[24,-2.5]},polys:[{v:'ABCD',col:0,fill:false}],segs:[...['EF','GH','IJ'].map(v=>({v,col:3,w:5})),...['KL','MN','OP','QR','ST','UV'].map(v=>({v,col:0,w:4}))],notes:[{at:[8.5,5.2],text:'reference'},{at:[15.5,5.2],text:'sample X'},{at:[22.5,5.2],text:'sample Y'},{at:[1,3],text:'−'},{at:[1,-3],text:'+'},{at:[28,3],text:'wells'},{at:[15,-5.4],text:'smaller DNA moves farther down toward +'}],view:[-1,31,-6.5,7]});
const TRY=[
 'Try it: a fictional gene has template DNA 3′-TACGGA-5′. Write the RNA sequence 5′ to 3′ using only six letters.',
 'Try it: a fictional reporter produces 12 units without an activator and 42 units with it. By what factor does output increase?',
 'Try it: a fictional PCR starts with 7 target DNA molecules. Assuming exact doubling per cycle, how many target molecules are present after 3 cycles?'
];
export default {
id:'science-h-ap-bio-gene-expression-and-regulation',subject:'science',level:5,grade:9,standard:'AP Biology Course and Exam Description (effective Fall 2025), Unit 6, topics 6.1–6.8',title:'Gene Expression and Regulation',
why:'Trace information from DNA to phenotype, predict how regulation and mutation change gene products, and interpret evidence from molecular experiments.',
skills:{structure:'DNA and RNA structure',replication:'DNA replication',transcription:'Transcription and RNA processing',translation:'Translation',regulation:'Regulation of gene expression',specialization:'Gene expression and cell specialization',mutations:'Mutations',biotechnology:'Biotechnology'},
outline:[['6.1','DNA and RNA Structure',['structure']],['6.2','DNA Replication',['replication']],['6.3','Transcription and RNA Processing',['transcription']],['6.4','Translation',['translation']],['6.5','Regulation of Gene Expression',['regulation']],['6.6','Gene Expression and Cell Specialization',['specialization']],['6.7','Mutations',['mutations']],['6.8','Biotechnology',['biotechnology']]],
steps:[
 {skill:'structure',say:'DNA stores hereditary information in nucleotide order. Each nucleotide has phosphate, a sugar and a base. DNA uses deoxyribose and T; RNA uses ribose and U. Covalent bonds link each backbone; hydrogen bonds join paired bases. Two-ring purines A and G pair with one-ring pyrimidines T or U and C. DNA strands are antiparallel: a 5′-AGTC-3′ strand pairs with 3′-TCAG-5′, not with a parallel copy.',eq:'DNA: A pairs with T; G pairs with C. RNA pairing: A with U.',pic:PAIR},
 {skill:'replication',say:'Before cell division, DNA is copied semiconservatively: each daughter duplex contains one old strand and one newly made strand. This preserves sequence by complementary pairing. Bacteria usually have a circular chromosome; eukaryotic nuclei usually have multiple linear chromosomes packaged with histones. Extra-chromosomal plasmids can occur in either group. Copying a chromosome is not the same as transcribing one gene.',eq:'one parental duplex → two duplexes, each old + new',pic:CONSERVE},
 {skill:'replication',say:'At a fork, helicase separates the strands and topoisomerase relieves twisting ahead. DNA polymerase extends a primer only at its 3′ end, so all new DNA grows 5′ to 3′. The leading strand grows toward the fork; lagging fragments grow away. After RNA primers are replaced with DNA, ligase seals backbone nicks. Proofreading reduces copying errors. The lagging strand never grows 3′ to 5′.',eq:'template read 3′ → 5′; new strand grows 5′ → 3′',pic:FORK},
 {skill:'transcription',say:'Transcription uses RNA polymerase to read one DNA template strand 3′ to 5′ and build complementary RNA 5′ to 3′. In this fictional segment, template 3′-TACCTT-5′ gives RNA 5′-AUGGAA-3′. The coding strand matches that RNA except T replaces U. mRNA carries coding information; tRNA carries amino acids and has an anticodon; rRNA forms part of the ribosome and catalyzes peptide-bond formation. RNA can also be a functional product itself.',eq:'template TACCTT → RNA AUGGAA',pic:board('Transcription: fictional six-base segment',['coding DNA:     5′-ATGGAA-3′','template DNA:   3′-TACCTT-5′','RNA product:    5′-AUGGAA-3′']),check:{prompt:TRY[0],answer:'AUGCCU',options:['AUGCCU','TACGGA','UACGGA'],hint:'Pair with the template: T→A, A→U, C→G, G→C. Keep the stated RNA direction.',pic:board('A different fictional template',['DNA template: 3′-TACGGA-5′','RNA product:  5′-??????-3′'])}},
 {skill:'transcription',say:'A typical eukaryotic pre-mRNA is processed before export: a modified guanine cap and a poly-A tail support stability and translation, while splicing removes introns and joins exons. In this fictional model, retained exons of 60, 80 and 60 nucleotides total 200 before cap and tail. Alternative splicing can retain different exon combinations, producing different RNAs from one gene. It changes RNA processing, not the DNA sequence.',eq:'mature transcript body = sum of retained exons',pic:SPLICE},
 {skill:'translation',say:'A ribosome initiates at a start codon, usually AUG, then reads mRNA 5′ to 3′ in triplets. Charged tRNAs pair anticodons with codons and deliver amino acids; rRNA catalyzes peptide bonds during elongation. A stop codon recruits a release factor, ending translation without adding an amino acid. The fictional AUG-GCU-UGG-UAA makes Met-Ala-Trp. Several codons can encode one amino acid; a codon is not an amino acid itself.',eq:'AUG | GCU | UGG | UAA → Met–Ala–Trp, then stop',pic:board('Read RNA codons, not DNA template triplets',['5′-AUG | GCU | UGG | UAA-3′','    Met      Ala      Trp      STOP','AUG sets the reading frame','3 amino acids; the stop adds none'])},
 {skill:'translation',say:'Translation occurs on cytoplasmic ribosomes, including those on rough ER in eukaryotes. Bacteria can translate an RNA while it is still being transcribed; a eukaryotic nucleus separates transcription from cytoplasmic translation. Nearly universal codon meanings support common ancestry. Retroviruses add another information route: reverse transcriptase copies RNA into DNA, which integrates into host DNA before transcription and translation produce viral components.',eq:'retrovirus: RNA → DNA → integrated DNA → RNA → protein',pic:flow('Retroviral information flow',['viral RNA','DNA copy','host DNA','new RNA'],'reverse transcription precedes integration and expression')},
 {skill:'regulation',say:'Regulation changes how much product a gene makes. In this negatively regulated inducible operon, a repressor binds an operator near the promoter and blocks transcription; an inducer can disable that repressor. In a repressible operon, an end product can activate a repressor and reduce enzyme production. Operon genes share transcriptional control. Do not confuse the operator DNA with the repressor protein, or induction with a change to the gene sequence.',eq:'inducer removes a brake; corepressor can apply a brake',pic:OPERON},
 {skill:'regulation',say:'Eukaryotic activators bind regulatory DNA such as enhancers and help recruit transcription machinery at promoters. DNA looping permits distant contact; genes on different chromosomes can share a transcription factor. Histone acetylation generally increases access, while promoter DNA methylation often accompanies reduced transcription. These epigenetic modifications do not change base sequence and can be reversible. Constitutive expression provides ongoing products; inducible expression responds to conditions.',eq:'DNA accessibility + regulatory proteins → transcription level',pic:CHROMATIN,check:{prompt:TRY[1],answer:3.5,options:[3.5,30,54],hint:'A fold change is stimulated output divided by baseline output.',pic:bars('Fictional reporter output (units)',['no activator','activator'],[12,42])}},
 {skill:'specialization',say:'A neuron and a skeletal muscle fiber from the same individual usually have essentially the same genes in their nuclei but express different combinations and amounts of genes. Regulatory proteins turn developmental signals into sequential expression programs. Ion-channel products support neuronal signaling; contractile proteins support muscle function. Different shape and function usually reflect differential expression, not deletion of every unused gene. The drawings show representative portions, not equal-sized whole cells.',eq:'shared genome + different expression programs → specialized cells',pic:CELLS},
 {skill:'specialization',say:'Gene expression can also change after transcription. Small regulatory RNAs can guide complexes that repress translation or promote target mRNA degradation. In this fictional assay, a targeted small RNA leaves mRNA at 8 units but reduces protein from 24 to 6 units. That supports regulation after RNA production, though it does not by itself exclude faster protein degradation. Measure both RNA and protein and use a nontargeting control before assigning a mechanism.',eq:'protein falls to 6 ÷ 24 = 0.25 of control while mRNA stays equal',pic:bars('Fictional assay: values normalized within each measure',['control RNA','small RNA: RNA','control protein','small RNA: protein'],[8,8,24,6])},
 {skill:'mutations',say:'A DNA mutation changes nucleotide sequence and can alter product type or amount. A synonymous substitution keeps the amino acid; missense changes it; nonsense creates a premature stop. In a coding region, an insertion or deletion not divisible by three shifts downstream codon grouping; three-base insertions or deletions preserve the downstream frame but can still alter protein function. This fictional RNA changes GAA (Glu) to UAA (stop), shortening the peptide. A regulatory mutation can change expression without changing a coding sequence.',eq:'AUG | GAA | CCG | UGA → AUG | UAA | CCG | UGA',pic:board('Fictional nonsense change: translate to the FIRST stop',['before: AUG | GAA | CCG | UGA','product: Met–Glu–Pro','after:   AUG | UAA | CCG | UGA','product: Met, then early release'])},
 {skill:'mutations',say:'Copying or repair errors, radiation and reactive chemicals can cause mutations; they do not arise because an organism needs them. Effects can be neutral, harmful or helpful depending on context. Nondisjunction changes chromosome number; deletions or rearrangements change chromosome structure. DNA can transfer between cells by transformation (DNA uptake), transduction (viral transfer) or conjugation (cell contact). Transposition moves DNA segments within or between DNA molecules. Related viruses can recombine in a shared host cell; selection acts on resulting heritable phenotypes.',eq:'genetic variation → phenotype in an environment → differential reproduction',pic:flow('Selection filters existing heritable variation',['variation','phenotypes','reproduction'],'a beneficial effect depends on environmental context')},
 {skill:'biotechnology',say:'PCR amplifies a chosen DNA region through repeated denaturation, primer annealing and extension by DNA polymerase. Primers define the region; heating separates strands. Under ideal doubling, a fictional 3 starting molecules give 3 × 2⁴ = 48 after four cycles. Real reactions may be less efficient and eventually plateau. Include a no-template control to detect contamination and a known-template positive control to check the reaction.',eq:'ideal target count = starting count × 2^(cycles)',pic:{t:'plot',title:'Fictional ideal PCR: x = cycles; y = target molecules',x:[0,4],y:[0,50],paths:[{pts:[[0,3],[1,6],[2,12],[3,24],[4,48]]}],points:[{x:4,y:48,label:'48'}]},check:{prompt:TRY[2],answer:56,options:[56,21,49],hint:'Double the count three times; do not multiply it by three.',pic:board('Fictional ideal PCR',['start: 7 target molecules','cycle 1 → cycle 2 → cycle 3','assume complete doubling at each cycle'])}},
 {skill:'biotechnology',say:'Gel electrophoresis compares DNA fragments: their negatively charged phosphate backbones move toward the positive electrode, and smaller linear fragments generally travel farther in the same gel. A size ladder calibrates the bands. Here fictional sample X matches both reference bands; Y matches only one. Matching band lengths supports similarity at the tested markers, not proof that entire genomes are identical. Band position reports size, not nucleotide order.',eq:'farther from wells → smaller fragment (same gel conditions)',pic:GEL},
 {skill:'biotechnology',say:'To manipulate DNA, restriction enzymes cut selected sequences and ligase joins compatible DNA pieces into a vector. Transformation introduces DNA into cells; a selectable marker helps recover cells carrying a vector, but does not prove the desired insert is correct. Sequencing checks nucleotide order; a reporter tests expression. A fictional colony that survives selection still needs an insert check and suitable controls before you can claim successful gene expression.',eq:'assemble DNA → transform cells → select → verify sequence and expression',pic:flow('Different tools answer different questions',['assemble','transform','select','verify'],'DNA uptake, insert identity and expression are separate claims')},
 {skill:'biotechnology',summary:true,say:'Follow the evidence from DNA to phenotype: replication copies DNA, transcription makes RNA, processing shapes transcripts, and translation makes polypeptides. Regulation changes product amounts; mutation changes sequence, with context-dependent effects. Track 5′ and 3′ ends and the reading frame. Choose PCR for amplification, gels for fragment-size comparisons, sequencing for base order, and RNA or protein assays for expression. Controls distinguish a supported explanation from an attractive guess.',eq:'sequence → RNA → protein → phenotype; test each link with the right evidence',pic:flow('Unit 6: connect information to evidence',['DNA','RNA','protein','phenotype'],'regulation changes output; mutation can change the instructions')}
],
progression:{requires:['science-h-ap-bio-heredity','science-h-ap-bio-cell-communication-and-cell-cycle'],operations:3,demand:'Track strand direction and reading frames, predict expression changes, and interpret controlled molecular experiments.'},
items(add){/* Round 11 (17 Oct): a pool rounding instruction never asks for more decimals than the stored answer has; "if needed" and significant-figure instructions are kept. Same copy in every unit that uses it (tests/pool-wording-round11.test.js). */const fitRound=(p,a)=>{if(typeof a!=='number'||!Number.isFinite(a)||/if needed/i.test(p))return p;const s=String(a);if(/e/.test(s))return p;const d=(s.split('.')[1]||'').length,W=['zero','one','two','three','four'],NEAR=['whole number','tenth','hundredth','thousandth','ten-thousandth'],m=/(, )?(\b(?:and )?(?:rounded|[Rr]ound) )?to (?:the nearest (tenth|hundredth|thousandth|ten-thousandth)( of a unit)?|(\d|one|two|three|four) (decimal places?|decimals?)\b)/.exec(p);if(!m)return p;const asked=m[3]?NEAR.indexOf(m[3]):/\d/.test(m[5])?+m[5]:W.indexOf(m[5]);if(asked<=d)return p;const head=p.slice(0,m.index),tail=p.slice(m.index+m[0].length);if(d>0)return head+m[0].replace(m[3]||m[5]+' '+m[6],m[3]?NEAR[d]:(/\d/.test(m[5])?d:W[d])+' '+(d===1?'decimal place':m[6]==='decimals'?'decimals':'decimal places'))+tail;const whole=[[/(^|[.?!;] )Give a decimal $/,'$1Give a whole number'],[/(^|[.?!] )Give the number without a percent sign $/,'$1Give a whole number without a percent sign'],[/(^|[.?!] )Give a signed number$/,'$1Give a signed whole number'],[/ as a percent $/,' as a whole-number percent'],[/(^|[.?!] )Give (?:the number|the answer|your answer|it) $/,'$1Give a whole number'],[/(^|[.?!] )(Give [^.?!,]*) $/,'$1$2 as a whole number']];for(const [re,w] of whole)if(re.test(head))return head.replace(re,w)+tail;if(m[2]&&/^[.?!]/.test(tail)&&/(^|[.?!;)] )$/.test(head))return head+(/; $/.test(head)?'give':'Give')+' a whole number'+tail;return head.replace(/ $/,'')+(m[1]?',':'')+(m[2]&&/^and /.test(m[2])?' and give a whole number':' as a whole number'+(m[4]?' of units':''))+tail;};const put0=add;add=(s,p,a,...r)=>put0(s,fitRound(p,a),a,...r);
 const seen=new Set(TRY);const put=(skill,prompt,answer,pic,explanation,accept)=>{if(seen.has(prompt))return;seen.add(prompt);add(skill,prompt,answer,pic,explanation,accept);};
 for(const [skill,rows] of Object.entries(FACTS))rows.forEach(([q,right,a,b,why],k)=>{const c=choose(right,[a,b],k);put(skill,`${q} ${c.text}. Answer A, B or C.`,c.letter,scenario(this.skills[skill],q),why,[right]);});
 for(const a of [17,23,28,34]){const g=50-a;put('structure',`A fictional double-stranded DNA sample contains ${a}% adenine. What percentage is guanine? Round to four decimals.`,g,tab('Fictional DNA composition',[['adenine',`${a}%`],['all four bases','100%']],['Measured value']),`A = T = ${a}%. The remaining ${100-2*a}% is shared equally by G and C, so G = ${g}%.`);}
 for(const n of [2,3,4,5])put('replication',`A fictional culture starts with one DNA duplex whose two strands are isotope-labeled. After ${n} complete semiconservative replication rounds in unlabeled medium, what percentage of duplexes still contain an original labeled strand? Assume no recombination or degradation. Round to four decimals.`,200/2**n,board('Fictional label tracing',[`rounds: ${n}`,'only the two original strands are labeled','all new nucleotides are unlabeled']),`The two old strands remain in two duplexes out of 2^${n} total: 2 ÷ ${2**n} × 100 = ${200/2**n}%.`);
 for(const seq of ['TACAGA','CGTATC','ATGGCT','GACTTA','CTAGGC','TTCGAC']){const rna=[...seq].map(b=>({A:'U',T:'A',C:'G',G:'C'})[b]).join('');put('transcription',`A fictional gene has template DNA 3′-${seq}-5′. Write the RNA sequence 5′ to 3′ using only six letters.`,rna,board('Fictional template strand',[`3′-${seq}-5′`,'RNA grows in the 5′ to 3′ direction']),`Complement each template base with RNA: A→U, T→A, C→G, G→C. The product is 5′-${rna}-3′.`);}
 for(const [a,b,c] of [[45,72,33],[81,24,66],[54,87,42]])put('transcription',`A fictional pre-mRNA has retained exons of ${a}, ${b} and ${c} nucleotides. After removing all introns, how many nucleotides are in the joined exon sequence, excluding the cap and poly-A tail?`,a+b+c,tab('Fictional retained exons',[['E1',`${a}`],['E2',`${b}`],['E3',`${c}`]],['Nucleotides']),`Only retained exons contribute: ${a} + ${b} + ${c} = ${a+b+c} nucleotides.`);
 for(const n of [8,11,16,23])put('translation',`A fictional open reading frame contains ${n} codons from its AUG start through its first in-frame stop, inclusive. How many amino acids does translation produce before any processing?`,n-1,board('Fictional complete reading frame',[`${n} codons total`,'includes AUG and one terminal stop','count amino acids before processing']),`The start codon contributes an amino acid but the stop does not: ${n} - 1 = ${n-1}.`);
 for(const [a,b] of [[8,28],[15,45],[14,35],[16,20]])put('regulation',`A fictional reporter produces ${a} units without an activator and ${b} units with it. By what factor does output increase? Round to four decimals.`,b/a,bars('Fictional reporter output (units)',['baseline','activator'],[a,b]),`Fold change compares final with initial output: ${b} ÷ ${a} = ${b/a}. It is not the difference in units.`);
 for(const [a,b] of [[40,10],[32,8],[50,20],[80,12]])put('specialization',`A fictional small-RNA experiment measures protein output of ${a} units in a nontargeting control and ${b} units after targeted treatment, with equal mRNA abundance. What percentage of control protein output remains? Round to four decimals.`,100*b/a,bars('Fictional protein output (units)',['control','targeted RNA'],[a,b]),`Treated output is ${b} of ${a} control units: ${b} ÷ ${a} × 100 = ${100*b/a}%. This measures remaining output, not percent reduction.`);
 for(const [start,cycles] of [[2,5],[5,4],[6,3],[9,5]])put('biotechnology',`A fictional PCR starts with ${start} target DNA molecules. Assuming exact doubling per cycle, how many target molecules are present after ${cycles} cycles?`,start*2**cycles,board('Fictional ideal PCR',[`start: ${start} molecules`,`complete cycles: ${cycles}`,'all target molecules double per cycle']),`Ideal amplification gives ${start} × 2^${cycles} = ${start*2**cycles} molecules. Real efficiency may be lower.`);
}
};
